<template>
  <div class="page-heading"><div><span class="eyebrow">ASSET REGISTER</span><h1>设备台账</h1><p>每台设备拥有独立编号，状态与借用流程同步。</p></div><el-button type="primary" @click="openForm()"><Icon name="plus" /> 登记设备</el-button></div>
  <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb20" />
  <section class="panel"><div class="filter-bar"><el-input v-model="filters.q" placeholder="搜索设备名称、编号或序列号" clearable class="search-input" @keyup.enter="search"><template #prefix><Icon name="search" /></template></el-input><el-select v-model="filters.status" placeholder="全部状态" clearable @change="search"><el-option v-for="(label, value) in assetStates" :key="value" :label="label" :value="value" /></el-select><el-select v-model="filters.category_id" placeholder="全部类别" clearable @change="search"><el-option v-for="category in categories" :key="category.id" :label="category.name" :value="category.id" /></el-select><el-button @click="search">查询</el-button><span class="result-count">{{ count }} 台设备</span></div>
  <el-table :data="items" v-loading="loading" empty-text="没有符合条件的设备"><el-table-column label="设备信息" min-width="205"><template #default="{ row }"><div class="asset-cell"><span class="asset-mini-icon"><Icon name="box" /></span><div><strong>{{ row.name }}</strong><div class="cell-sub">{{ row.code }}</div></div></div></template></el-table-column><el-table-column prop="category_name" label="设备类别" min-width="115" /><el-table-column label="当前状态" min-width="125"><template #default="{ row }"><StatusPill :status="row.status" asset /></template></el-table-column><el-table-column label="当前去向" min-width="155"><template #default="{ row }"><div>{{ row.borrower_name || '—' }}</div><div class="cell-sub">{{ row.store_name || '总部设备池' }}</div></template></el-table-column><el-table-column prop="serial_number" label="序列号" min-width="145" /><el-table-column label="操作" width="145" fixed="right"><template #default="{ row }"><el-button v-if="row.status === 'available'" link type="primary" @click="openForm(row)">编辑</el-button><el-button v-if="row.status === 'maintenance' && session.user?.role === 'custodian'" link type="primary" @click="repair(row)">确认修复</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination :current-page="page" :page-size="20" :total="count" layout="total, prev, pager, next" @current-change="value => { page = value; load() }" /></div></section>
  <div class="context-note"><Icon name="help" /> 设备状态由借用、交接和验收产生。编辑设备资料不会直接改变其占用状态。</div>
  <el-dialog v-model="editing" :title="editingId ? '编辑设备资料' : '登记新设备'" width="520px" :close-on-click-modal="false"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="设备编号" prop="code"><el-input v-model="form.code" maxlength="50" placeholder="例如 SF-SCAN-021" /></el-form-item><el-form-item label="设备名称" prop="name"><el-input v-model="form.name" maxlength="100" placeholder="例如 无线条码扫码枪" /></el-form-item><el-form-item label="设备类别" prop="category_id"><el-select v-model="form.category_id" class="full-width"><el-option v-for="category in categories" :key="category.id" :label="category.name" :value="category.id" /></el-select></el-form-item><el-form-item label="序列号" prop="serial_number"><el-input v-model="form.serial_number" maxlength="100" placeholder="填写设备本体序列号" /></el-form-item></el-form><template #footer><el-button @click="editing = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存设备</el-button></template></el-dialog>
</template>
<script setup>
import { ref, reactive, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { get, post, patch, rows, report } from '../api/client'
import { assetStates } from '../utils/format'
import { useSession } from '../stores/session'
import Icon from '../ui/Icon.vue'
import StatusPill from '../ui/StatusPill.vue'
const session = useSession()
const items = ref([]), count = ref(0), page = ref(1), categories = ref([]), loading = ref(false), saving = ref(false), error = ref(''), editing = ref(false), editingId = ref(null), formRef = ref()
const filters = reactive({ q: '', status: '', category_id: '' }), form = reactive({ code: '', name: '', category_id: null, serial_number: '' }), rules = Object.fromEntries(['code', 'name', 'category_id', 'serial_number'].map(key => [key, [{ required: true, message: '请完整填写该项', trigger: 'blur' }]]))
async function load() { loading.value = true; error.value = ''; try { const data = await get('assets/', { ...filters, page: page.value }); items.value = rows(data); count.value = data.count ?? items.value.length } catch (e) { error.value = e.userMessage } finally { loading.value = false } }
function search() { page.value = 1; load() }
function openForm(asset) { editingId.value = asset?.id || null; Object.assign(form, { code: asset?.code || '', name: asset?.name || '', category_id: asset?.category_id || null, serial_number: asset?.serial_number || '' }); editing.value = true }
async function save() { if (saving.value || !await formRef.value.validate().catch(() => false)) return; saving.value = true; try { editingId.value ? await patch(`assets/${editingId.value}/`, form) : await post('assets/', form); editing.value = false; ElMessage.success('设备资料已保存。'); await load() } catch (e) { report(e) } finally { saving.value = false } }
async function repair(asset) { try { const { value } = await ElMessageBox.prompt('请确认设备已完成维修和功能检查，并记录处理说明。', `确认修复 · ${asset.code}`, { inputType: 'textarea', inputValidator: value => !!value?.trim() || '请填写维修与检查说明', confirmButtonText: '确认恢复可用', cancelButtonText: '取消' }); await post(`assets/${asset.id}/repair/`, { reason: value }); ElMessage.success('设备已恢复可用。'); await load() } catch (e) { if (e !== 'cancel' && e !== 'close') report(e) } }
onMounted(async () => { await load(); try { categories.value = rows(await get('categories/')) } catch (e) { report(e) } })
</script>
